package gofiles

import (
	"os"
	"path/filepath"
	"testing"
)

func TestWalk(t *testing.T) {
	dir := t.TempDir()
	files := map[string]string{
		"a.go":          "package a\n",
		"a_test.go":     "package a\n",
		"sub/b.go":      "// Code generated by x. DO NOT EDIT.\n\npackage sub\n",
		"testdata/c.go": "package broken {",
		"vendor/v/v.go": "package v\n",
		"notes.txt":     "x",
	}
	for name, body := range files {
		p := filepath.Join(dir, name)
		_ = os.MkdirAll(filepath.Dir(p), 0o755)
		if err := os.WriteFile(p, []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	all, err := Walk([]string{dir + "/..."})
	if err != nil || len(all) != 2 {
		t.Fatalf("Walk = %+v, %v", all, err)
	}
	gen := 0
	for _, f := range all {
		if f.Generated {
			gen++
		}
	}
	if gen != 1 {
		t.Fatalf("generated count = %d", gen)
	}
	top, err := Walk([]string{dir})
	if err != nil || len(top) != 1 {
		t.Fatalf("non-recursive Walk = %+v, %v", top, err)
	}
	t.Chdir(dir)
	if cur, err := Walk(nil); err != nil || len(cur) != 2 {
		t.Fatalf("default pattern = %+v, %v", cur, err)
	}
	if _, err := Walk([]string{"/..."[:0] + "./..."}); err != nil {
		t.Fatal(err)
	}
	_ = os.WriteFile(filepath.Join(dir, "bad.go"), []byte("package {"), 0o600)
	if _, err := Walk([]string{"."}); err == nil {
		t.Fatal("parse error: want error")
	}
}
